  const handledOrphanedToolUseIds = new Set<string>()
  // `findUnresolvedToolUse` deja `message.id` opcional porque describe
  // cualquier mensaje del asistente; el handler de permisos huerfanos exige
  // que venga presente. La guarda estrecha el resultado sin ensanchar el
  // tipo que publica sessionStorage.
  function isResolvedToolUseMessage<T extends { message: { id?: string } }>(
    candidate: T | null,
  ): candidate is T & { message: { id: string } } {
    return candidate !== null && typeof candidate.message.id === 'string'
  }
  structuredIO.setUnexpectedResponseCallback(async message => {
    await handleOrphanedPermissionResponse({
      message,
      handledToolUseIds: handledOrphanedToolUseIds,
      onEnqueued: () => {
        // The first message of a session might be the orphaned permission
        // check rather than a user prompt, so kick off the loop.
        void run()
      },
      deps: {
        findUnresolvedToolUse: async toolUseID => {
          const found = await findUnresolvedToolUse(toolUseID)
          return isResolvedToolUseMessage(found) ? found : null
        },
        enqueue,
        logDebug: logForDebugging,
      },
    })
  })"}],
